urn:mrr:question-model:01KY35BNMVM9WN2AKY6QBKNZJ4	1	mrr/v1alpha1	QuestionModel	urn:mrr:practice:01KY35BNKB3C05NTXYHEKC97SX	2026-07-21 20:20:00.283698+00	urn:mrr:agent-role:01KY35BNKB3C05NTXYHEKC97SV	sha256:832b8d6e432867d979200f9a549efee215a28c0c8bf47b14576350d285ba619e	\N	null	{"id": "urn:mrr:question-model:01KY35BNMVM9WN2AKY6QBKNZJ4", "kind": "QuestionModel", "scope": {"time": "atlas snapshots pinned 2026-07-21 at the recorded content hashes", "conditions": ["work must be catalogued in the pinned works-atlas snapshot, not merely mentioned in secondary commentary", "theory-side corroboration is drawn only from the pinned theory-atlas snapshot's own model-collapse keyword match over tags/summary/work"], "population": "works in the pinned works-atlas snapshot (corpora/model-collapse/works-atlas.snapshot.json, sha256:9d14e877efb245cc04b8451734b26285a274dda0418f5131db257d2e4312d373, 214 verified data/AI artworks) whose own `clusters` array contains 7 (\\"AI self-consumption\\" per src/data/field/clusters.json) — corroborated against the pinned theory-atlas snapshot (corpora/model-collapse/theory-atlas.snapshot.json, sha256:f712ea4e9c6b9137fa180ad91e73a86d8d09862792f33174c77acd76a891e610, 87 provenance-verified sources) for the model-collapse mechanism's own existence"}, "status": "draft", "revision": 1, "created_at": "2026-07-21T20:20:00.283698Z", "created_by": "urn:mrr:agent-role:01KY35BNKB3C05NTXYHEKC97SV", "api_version": "mrr/v1alpha1", "practice_id": "urn:mrr:practice:01KY35BNKB3C05NTXYHEKC97SX", "content_hash": "sha256:832b8d6e432867d979200f9a549efee215a28c0c8bf47b14576350d285ba619e", "raw_question": "Do works catalogued under AI-self-consumption actually instantiate the model-collapse mechanism the technical literature describes, or merely reference it?", "claim_type_sought": "interpretive", "load_bearing_terms": ["model-collapse mechanism", "instantiate", "reference", "independent corroboration"]}
urn:mrr:question-model:01KY35BNMVM9WN2AKY6QBKNZJ4	2	mrr/v1alpha1	QuestionModel	urn:mrr:practice:01KY35BNKB3C05NTXYHEKC97SX	2026-07-21 20:20:00.292784+00	urn:mrr:agent-role:01KY35BNKB3C05NTXYHEKC97SV	sha256:c17392ec762d8382500d54d8a2f82d153a78b8186515c260ae8dd53236d679cc	\N	null	{"id": "urn:mrr:question-model:01KY35BNMVM9WN2AKY6QBKNZJ4", "kind": "QuestionModel", "scope": {"time": "atlas snapshots pinned 2026-07-21 at the recorded content hashes", "conditions": ["work must be catalogued in the pinned works-atlas snapshot, not merely mentioned in secondary commentary", "theory-side corroboration is drawn only from the pinned theory-atlas snapshot's own model-collapse keyword match over tags/summary/work"], "population": "works in the pinned works-atlas snapshot (corpora/model-collapse/works-atlas.snapshot.json, sha256:9d14e877efb245cc04b8451734b26285a274dda0418f5131db257d2e4312d373, 214 verified data/AI artworks) whose own `clusters` array contains 7 (\\"AI self-consumption\\" per src/data/field/clusters.json) — corroborated against the pinned theory-atlas snapshot (corpora/model-collapse/theory-atlas.snapshot.json, sha256:f712ea4e9c6b9137fa180ad91e73a86d8d09862792f33174c77acd76a891e610, 87 provenance-verified sources) for the model-collapse mechanism's own existence"}, "status": "accepted", "revision": 2, "created_at": "2026-07-21T20:20:00.292784+00:00", "created_by": "urn:mrr:agent-role:01KY35BNKB3C05NTXYHEKC97SV", "api_version": "mrr/v1alpha1", "practice_id": "urn:mrr:practice:01KY35BNKB3C05NTXYHEKC97SX", "content_hash": "sha256:c17392ec762d8382500d54d8a2f82d153a78b8186515c260ae8dd53236d679cc", "raw_question": "Do works catalogued under AI-self-consumption actually instantiate the model-collapse mechanism the technical literature describes, or merely reference it?", "claim_type_sought": "interpretive", "load_bearing_terms": ["model-collapse mechanism", "instantiate", "reference", "independent corroboration"]}
urn:mrr:concept-charter:01KY35BNNDFK37GMC5CT9BMRM9	1	mrr/v1alpha1	ConceptCharter	urn:mrr:practice:01KY35BNKB3C05NTXYHEKC97SX	2026-07-21 20:20:00.301753+00	urn:mrr:agent-role:01KY35BNKB3C05NTXYHEKC97SV	sha256:2d3ef770bde508c46eb75f957aeab840ef5d7d14deca629db71ced6c7b8f31ac	\N	null	{"id": "urn:mrr:concept-charter:01KY35BNNDFK37GMC5CT9BMRM9", "kind": "ConceptCharter", "status": "draft", "entries": [{"term": "model-collapse mechanism", "entry_id": "model-collapse-mechanism-v1", "definition": "The technical-literature process by which a generative model trained iteratively on its own (or its predecessors') outputs suffers a measurable degeneration of its output distribution — narrowed tail coverage, amplified mode bias — across successive training generations.", "scope_note": "Local operationalization for this profile only; not a claim about every use of the phrase in the wider literature. Applied here (task-packets/K1-T04.yaml) to the three theory-atlas papers matching a fixed, disclosed keyword search (\\"model collapse\\", \\"model-collapse\\", \\"self-consuming\\", \\"self-consumption\\", \\"autophagy\\", \\"MAD\\", \\"curse of recursion\\") over tags/summary/work: shumailov-curse-of-recursion, alemohammad-self-consuming-generative-models-go-mad, gerstgrasser-is-model-collapse-inevitable."}, {"term": "instantiate", "entry_id": "instantiate-vs-reference-v1", "definition": "A work 'instantiates' the mechanism when its own production pipeline demonstrably trains on model-generated outputs across at least two generations; a work merely 'references' the mechanism when it only discusses, depicts, or alludes to it without demonstrable recursive training. Decision procedure, applied directly against each work's own `decisive_move` + `source_url` field in the pinned works-atlas snapshot: Step 1 -- does the work's own documented production process feed model-GENERATED output back in as training input for a SUBSEQUENT generation of the same (or a continuous) generative pipeline, across at least two generations? If yes -> instantiates. Step 2 -- if the work only depicts, critiques, or thematizes the phenomenon, or trains on human-authored material (even the artist's own prior writing) without a demonstrable model-generation-to-model-generation loop -> references only. Ambiguous or incompletely disclosed cases -> qualifies, assessed individually, never force-fit into either bucket.", "scope_note": "Applied here (task-packets/K1-T04.yaml) to the 15 works-atlas entries whose own `clusters` array contains 7 (\\"AI self-consumption\\"); each classification's basis is recorded in corpora/model-collapse/corpus-entries.json's own `extraction.classification_basis` field, quoting the exact `decisive_move` text it rests on."}, {"term": "independent corroboration", "entry_id": "corroboration-floor-v1", "definition": "This entry names a SENSITIVITY VARIATION on the eligibility threshold this profile's own `eligibility_rules` already uses — specifically, how many distinct, independent source families must corroborate an analysis's supporting or contradicting side before that side counts as adequately corroborated. The BASE run's own protocol-parameters sidecar sets `contested.min_independent_source_families = 1` (an analysis may be called 'contested' if even a single independent family supports it, so long as at least one independent family also contradicts it) alongside `supported.min_independent_source_families = 2` (an analysis may only be called 'supported' with at least two independent corroborating families) — an asymmetry between the two labels' own evidentiary bar. `corroboration-floor-v1` RAISES the 'contested' floor to match the 'supported' floor exactly — `min_independent_source_families = 2` for BOTH outcome labels — asking whether this profile's own classifications still hold when a single independent supporting family is no longer sufficient to call an analysis 'contested' either, requiring the SAME minimum corroboration strength regardless of which side of a finding is being assessed. This is explicitly a THRESHOLD VARIATION over the existing `eligibility_rules` mechanism (MRR-MTH-018) — it changes how much independent corroboration is required before a classification is reported, not what 'instantiate' or 'reference' or 'model-collapse mechanism' MEANS. It is NOT a second, rival operationalization of the mechanism-vs-reference distinction (contrast entry `instantiate-vs-reference-v1`, whose own definition this entry leaves entirely untouched) and MUST NOT be read as one.", "scope_note": "Applied here (task-packets/K1-T04b.yaml) as this run's own sole declared `MethodProtocol.sensitivity_variations` entry, executed via the `SensitivityVariationParameters` sidecar `corpora/model-collapse/run2-corroboration-floor/sensitivity-variation-parameters.corroboration-floor-v1.sidecar.json` over the SAME corpus and base protocol-parameters run 1's own base classification already used (`corpora/model-collapse/corpus-entries.json`, `corpora/model-collapse/protocol-parameters.sidecar.json`, both reused unchanged by direct path reference, never copied or re-extracted, per derived_decisions (b))."}], "revision": 1, "created_at": "2026-07-21T20:20:00.301753Z", "created_by": "urn:mrr:agent-role:01KY35BNKB3C05NTXYHEKC97SV", "api_version": "mrr/v1alpha1", "practice_id": "urn:mrr:practice:01KY35BNKB3C05NTXYHEKC97SX", "content_hash": "sha256:2d3ef770bde508c46eb75f957aeab840ef5d7d14deca629db71ced6c7b8f31ac"}
urn:mrr:concept-charter:01KY35BNNDFK37GMC5CT9BMRM9	2	mrr/v1alpha1	ConceptCharter	urn:mrr:practice:01KY35BNKB3C05NTXYHEKC97SX	2026-07-21 20:20:00.31442+00	urn:mrr:agent-role:01KY35BNKB3C05NTXYHEKC97SV	sha256:cc67a9ce32f9164b0bd0a3ed66619ea3ae78c3760e2e8f61178e167425dd6a2c	\N	null	{"id": "urn:mrr:concept-charter:01KY35BNNDFK37GMC5CT9BMRM9", "kind": "ConceptCharter", "status": "accepted", "entries": [{"term": "model-collapse mechanism", "entry_id": "model-collapse-mechanism-v1", "definition": "The technical-literature process by which a generative model trained iteratively on its own (or its predecessors') outputs suffers a measurable degeneration of its output distribution — narrowed tail coverage, amplified mode bias — across successive training generations.", "scope_note": "Local operationalization for this profile only; not a claim about every use of the phrase in the wider literature. Applied here (task-packets/K1-T04.yaml) to the three theory-atlas papers matching a fixed, disclosed keyword search (\\"model collapse\\", \\"model-collapse\\", \\"self-consuming\\", \\"self-consumption\\", \\"autophagy\\", \\"MAD\\", \\"curse of recursion\\") over tags/summary/work: shumailov-curse-of-recursion, alemohammad-self-consuming-generative-models-go-mad, gerstgrasser-is-model-collapse-inevitable."}, {"term": "instantiate", "entry_id": "instantiate-vs-reference-v1", "definition": "A work 'instantiates' the mechanism when its own production pipeline demonstrably trains on model-generated outputs across at least two generations; a work merely 'references' the mechanism when it only discusses, depicts, or alludes to it without demonstrable recursive training. Decision procedure, applied directly against each work's own `decisive_move` + `source_url` field in the pinned works-atlas snapshot: Step 1 -- does the work's own documented production process feed model-GENERATED output back in as training input for a SUBSEQUENT generation of the same (or a continuous) generative pipeline, across at least two generations? If yes -> instantiates. Step 2 -- if the work only depicts, critiques, or thematizes the phenomenon, or trains on human-authored material (even the artist's own prior writing) without a demonstrable model-generation-to-model-generation loop -> references only. Ambiguous or incompletely disclosed cases -> qualifies, assessed individually, never force-fit into either bucket.", "scope_note": "Applied here (task-packets/K1-T04.yaml) to the 15 works-atlas entries whose own `clusters` array contains 7 (\\"AI self-consumption\\"); each classification's basis is recorded in corpora/model-collapse/corpus-entries.json's own `extraction.classification_basis` field, quoting the exact `decisive_move` text it rests on."}, {"term": "independent corroboration", "entry_id": "corroboration-floor-v1", "definition": "This entry names a SENSITIVITY VARIATION on the eligibility threshold this profile's own `eligibility_rules` already uses — specifically, how many distinct, independent source families must corroborate an analysis's supporting or contradicting side before that side counts as adequately corroborated. The BASE run's own protocol-parameters sidecar sets `contested.min_independent_source_families = 1` (an analysis may be called 'contested' if even a single independent family supports it, so long as at least one independent family also contradicts it) alongside `supported.min_independent_source_families = 2` (an analysis may only be called 'supported' with at least two independent corroborating families) — an asymmetry between the two labels' own evidentiary bar. `corroboration-floor-v1` RAISES the 'contested' floor to match the 'supported' floor exactly — `min_independent_source_families = 2` for BOTH outcome labels — asking whether this profile's own classifications still hold when a single independent supporting family is no longer sufficient to call an analysis 'contested' either, requiring the SAME minimum corroboration strength regardless of which side of a finding is being assessed. This is explicitly a THRESHOLD VARIATION over the existing `eligibility_rules` mechanism (MRR-MTH-018) — it changes how much independent corroboration is required before a classification is reported, not what 'instantiate' or 'reference' or 'model-collapse mechanism' MEANS. It is NOT a second, rival operationalization of the mechanism-vs-reference distinction (contrast entry `instantiate-vs-reference-v1`, whose own definition this entry leaves entirely untouched) and MUST NOT be read as one.", "scope_note": "Applied here (task-packets/K1-T04b.yaml) as this run's own sole declared `MethodProtocol.sensitivity_variations` entry, executed via the `SensitivityVariationParameters` sidecar `corpora/model-collapse/run2-corroboration-floor/sensitivity-variation-parameters.corroboration-floor-v1.sidecar.json` over the SAME corpus and base protocol-parameters run 1's own base classification already used (`corpora/model-collapse/corpus-entries.json`, `corpora/model-collapse/protocol-parameters.sidecar.json`, both reused unchanged by direct path reference, never copied or re-extracted, per derived_decisions (b))."}], "revision": 2, "created_at": "2026-07-21T20:20:00.314420+00:00", "created_by": "urn:mrr:agent-role:01KY35BNKB3C05NTXYHEKC97SV", "api_version": "mrr/v1alpha1", "practice_id": "urn:mrr:practice:01KY35BNKB3C05NTXYHEKC97SX", "content_hash": "sha256:cc67a9ce32f9164b0bd0a3ed66619ea3ae78c3760e2e8f61178e167425dd6a2c"}
