urn:mrr:evidence-anchor:01KY35BP2WJD0XPVKV4YKVJCS4	1	mrr/v1alpha1	EvidenceAnchor	urn:mrr:practice:01KY35BNKB3C05NTXYHEKC97SX	2026-07-21 20:20:00.732828+00	urn:mrr:agent-role:01KY35BNKB3C05NTXYHEKC97SV	sha256:eedca97f13acc1a19bee68dd9e88313fd86a7759c3ae5ec8755b0e7e95d01b22	\N	null	{"id": "urn:mrr:evidence-anchor:01KY35BP2WJD0XPVKV4YKVJCS4", "kind": "EvidenceAnchor", "relation": "contradicts", "revision": 1, "created_at": "2026-07-21T20:20:00.732828Z", "created_by": "urn:mrr:agent-role:01KY35BNKB3C05NTXYHEKC97SV", "anchor_kind": "text", "api_version": "mrr/v1alpha1", "practice_id": "urn:mrr:practice:01KY35BNKB3C05NTXYHEKC97SX", "content_hash": "sha256:eedca97f13acc1a19bee68dd9e88313fd86a7759c3ae5ec8755b0e7e95d01b22", "extractor_id": "urn:mrr:agent-role:01KY35BNKB3C05NTXYHEKC97SV", "snapshot_hash": "sha256:a81ecc959fe5365b1c4527290ed3e14e072d559f738bf816ff0db3ceb155e3c7", "source_record_id": "urn:mrr:source-record:01KY35BP2NBKNYKDACQNBF8Q3W", "extraction_method": "human_curated_corpus_excerpt", "transformation_chain": [], "anchor_validation_status": "validated"}
urn:mrr:evidence-matrix:01KY35BP33JVF45T30NQW9FJX4	1	mrr/v1alpha1	EvidenceMatrix	urn:mrr:practice:01KY35BNKB3C05NTXYHEKC97SX	2026-07-21 20:20:00.739421+00	urn:mrr:agent-role:01KY35BNKB3C05NTXYHEKC97SV	sha256:a0ec654f351e873dae1605d606cd41914587fe3a7227c572f92eaefe07640963	\N	null	{"id": "urn:mrr:evidence-matrix:01KY35BP33JVF45T30NQW9FJX4", "kind": "EvidenceMatrix", "rows": [{"row_id": "theory-shumailov-curse-of-recursion", "extraction": {"classification_basis": "tags: [\\"maschine/ki\\",\\"computation\\",\\"fehler\\"]; summary: \\"Shows generative models degrade when trained on their own output — model collapse\\" — a primary theoretical source directly describing the mechanism; classified supports."}, "source_record_id": "urn:mrr:source-record:01KY35BNVD4H4MRYQRJA5ZH9QN", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BNVPFM57RM9W5BZJVX4Q", "verification_status": "verified", "claim_relevant_finding": "Shows generative models degrade when trained on their own output — model collapse: the tails of the distribution vanish first. Peer-reviewed as 'AI models collapse when trained on recursively generated data', Nature 631 (2024); open access on arXiv."}, {"row_id": "theory-alemohammad-self-consuming-mad", "extraction": {"classification_basis": "tags: [\\"maschine/ki\\",\\"computation\\",\\"fehler\\"]; summary: \\"autophagous training loops across image models ... progressively decays — termed Model Autophagy Disorder (MAD)\\" — a primary theoretical source, independent author team and venue from shumailov/gerstgrasser; classified supports."}, "source_record_id": "urn:mrr:source-record:01KY35BNVYMFN1ZTAEE9D192DJ", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BNW6DDEJDPW63VS7XTKR", "verification_status": "verified", "claim_relevant_finding": "Analyzes autophagous training loops across image models: without enough fresh real data in each generation, quality or diversity progressively decays — termed Model Autophagy Disorder (MAD). Open access on arXiv; no further formal venue recorded in the atlas."}, {"row_id": "theory-gerstgrasser-model-collapse-inevitable", "extraction": {"classification_basis": "tags: [\\"maschine/ki\\",\\"computation\\"]; summary: \\"accumulating synthetic data alongside real data ... bounds the error across LLMs, diffusion models and VAEs\\" — a primary theoretical source corroborating the same mechanism from a third, independent author team and venue; classified supports."}, "source_record_id": "urn:mrr:source-record:01KY35BNWDGA9YK34T1M1W4MYV", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BNWMBJDXBTKXQBKWZ95H", "verification_status": "verified", "claim_relevant_finding": "Shows collapse is not fate: accumulating synthetic data alongside real data — instead of replacing it — bounds the error across LLMs, diffusion models and VAEs. Also published at COLM 2024; open access on arXiv."}, {"row_id": "works-heaney-ent-non-earthly-delights", "extraction": {"classification_basis": "decisive_move describes a physical sculpture about quantum computing and surveillance capitalism, with no documented model-generation-to-model-generation training loop at all (ConceptCharter instantiate-vs-reference-v1 Step 2: thematizes AI surveillance rather than instantiating the mechanism); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY35BNWYVBGMAHR6BVTM7HGM", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BNX5TJDWDTXA2WRZTTS3", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"A physical 'quantum cyborg' sculpture (mild steel, fibreglass, acrylic, plus AR layers) staging Bosch's Garden of Earthly Delights as a warning about quantum computing's coming acceleration of AI-driven surveillance capitalism; Heaney explicitly frames dissolving/'sliming' as a strategy of resistance against detection systems.\\""}, {"row_id": "works-wilding-ai-lab", "extraction": {"classification_basis": "decisive_move describes examining the training/generation process as artistic material, but discloses no demonstrable model-output-fed-back-as-training-input loop across >=2 generations (Step 1 not cleared); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY35BNXBX6JWW8HSCV7BN0AZ", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BNXJMP2QQXCBWCZ88EBW", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"An open, participatory lab inside a spatial-audio dome where invited artists collectively 'reopen the black box' of generative AI models in public, treating the training/generation process itself — not just its output — as the artistic material.\\""}, {"row_id": "works-chronus-ai-delivered-abject", "extraction": {"classification_basis": "decisive_move describes GAN-trained works probing epistemological breakdown, but discloses no recursive model-generation-to-model-generation training loop (Step 1 not cleared); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY35BNXT9YWHA6VGD72HF3JB", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BNY24V3FCKR31JVEH672", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"Group exhibition of GAN-trained films, a real-time AI dialogue-generating website, and an 'artificial counter-intelligence machine,' collectively probing where AI's competence gives way to abjection and epistemological breakdown.\\""}, {"row_id": "works-baudelaire-en-attendant-le-recit", "extraction": {"classification_basis": "decisive_move describes live inference-time conversation between already-trained models, not model-generated output fed back as training data for a subsequent generation (Step 1 not cleared — a looping CONVERSATION, not a looping TRAINING process); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY35BNY91H52992031D9R6MZ", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BNYG4N72M78Z0JTTW20W", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"Three chatbot models (ChatGPT, Claude, Mistral) are each given a character and voice through a speaker on one of three benches arranged in a triangle, and left to converse live about AI anxiety and 'the end of grand narratives' — an unscripted, looping machine dialogue restaged as improvised theatre, restarting every seven minutes.\\""}, {"row_id": "works-kurant-errorism", "extraction": {"classification_basis": "decisive_move states the model is trained on \\"her own writings\\" (the artist's own prior, human-authored text), not a PRIOR GENERATION OF THE MODEL'S OWN output — this is exactly ConceptCharter instantiate-vs-reference-v1 Step 2's named case (\\"trains on human-authored material (even the artist's own prior writing) without a demonstrable model-generation-to-model-generation loop\\"); a genuinely ambiguous, flagged case (task-packets/K1-T04.yaml derived_decisions (e)), resolved here per the charter's own Step 2 text; classified references-only/contradicts, not qualifies, because the atlas's own decisive_move discloses the input as the artist's own writing, not the model's own prior-generation output."}, "source_record_id": "urn:mrr:source-record:01KY35BNYQAAM6WDC1AEBF45BR", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BNYYP1DWG6HDV9MVFWV1", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"Kurant feeds her own writings into GPT-2 and GPT-3 and renders the output as a holographic animation, literally closing the loop of a model trained on and regurgitating one author's own words — a small, self-contained demonstration of the recursive self-consumption/collapse dynamic at stake in cluster 7.\\""}, {"row_id": "works-raikhy-hallucinations-of-an-artifact", "extraction": {"classification_basis": "decisive_move describes live performance collaboration with a generative-AI avatar, with no documented recursive training loop across generations (Step 1 not cleared); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY35BNZ4C9VJZ4J4GJ6E4909", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BNZAMXYD9GC65G7K4MVC", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"Dancers improvise alongside a generative-AI avatar to invent speculative alternate lives for a prehistoric Indus Valley bronze statue, using an AI model as collaborator in reanimating an artifact whose original meaning is otherwise irrecoverable.\\""}, {"row_id": "works-ubermorgen-next-biennial-machine", "extraction": {"classification_basis": "decisive_move states the model is trained once on real Biennial/Whitney archives and then generates continuously, with no described retraining on its own prior-generation output (Step 1 not cleared); classified references-only/contradicts. Atlas verify_status is 'toVerify', not 'verified' — mapped to CorpusEntry verification_status 'pending' (task-packets/K1-T04.yaml derived_decisions (c)). The row is never dropped from the frozen matrix (MRR-MTH-015). Its own 'contradicts' evidence_relation still groups it into the contradicting-entry set the claim's own assertion text is built from (mrr.services.node_runtime.synthesis_executor._build_assertion has no verification-status filter), but mrr.domain.source_independence.distinct_independent_source_family_count only counts 'verified' rows, so this row contributes zero to the numeric contradicting-family tally that actually determines eligibility (13, not 14, distinct families) — the same 'verified'-only rule also excludes it from the separate min_included_sources kill-condition count. The eligibility outcome is unaffected either way."}, "source_record_id": "urn:mrr:source-record:01KY35BNZH98AF2VN023JZDB4W", "verification_status": "pending", "claim_relevant_finding": "decisive_move: \\"An AI trained on real Biennial and Whitney archives endlessly hallucinates fake artist biographies and press releases, exposing algorithmic curation's absurdity by actually letting a machine attempt it, live, forever.\\""}, {"row_id": "works-mavropoulou-sleight-of-the-machine", "extraction": {"classification_basis": "decisive_move describes a single AI video model's inference-time failures kept on screen, with no documented recursive retraining loop across generations (Step 1 not cleared); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY35BNZRE5MFFTKPPM0JWTW1", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BNZYJG0Q9K8F473T30DB", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"An AI video model is cast as a stage magician performing sleight-of-hand; rather than concealing the model's characteristic failures (hands multiplying, morphing, defying physics), the film keeps every glitch on screen as the actual 'trick' — generative failure turned into the evidentiary content.\\""}, {"row_id": "works-hammond-v3-model-collapse", "extraction": {"classification_basis": "decisive_move states plainly: \\"each exhibition's own photographs and collages are fed back as training data for the next\\" — model-GENERATED output (the prior exhibition's own photographs/collages) fed back as training input for a SUBSEQUENT generation of a continuous pipeline, across at least three named generations (V1-V4) — clears ConceptCharter instantiate-vs-reference-v1 Step 1 cleanly, and the atlas's own text names the result \\"literalizes AI model collapse\\"; classified instantiates/supports."}, "source_record_id": "urn:mrr:source-record:01KY35BP05ZVMXH38B68J4RKHQ", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BP0BS2YDKEPRPG0N0VST", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"Third chapter of a four-part project in which each exhibition's own photographs and collages are fed back as training data for the next - literalizes AI model collapse as a visible, physically-installed material process, and draws an explicit parallel between data mining and geological mining extraction.\\""}, {"row_id": "works-hailesilassie-6500-alphabets", "extraction": {"classification_basis": "decisive_move describes a physical installation of digitized pictographs proposing an alternative epistemics, with no generative-model recursive training loop described at all (Step 1 not cleared, not even a generative-AI production pipeline); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY35BP0JYJ39T8YWS521NHYR", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BP0S7PBYYK130S9CXKX8", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"Large-scale dome installation built from 6,500 digitized African pictographs, syllabaries and ideographs (extending the artist's 2019–2023 'Ancestral Algorithm' project) that reframes 'algorithm' as 'algo + rhythm', proposing indigenous knowledge systems as an alternative computational epistemics rather than an ornament to it.\\""}, {"row_id": "works-salu-ginzburg-cybernetics-or-ghosts", "extraction": {"classification_basis": "decisive_move describes human-authored fiction responding to a 1967 essay, with no generative-model training loop of any kind described (Step 1 not cleared, not even a generative-AI production pipeline); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY35BP10KEQADBQXGZD6B7MH", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BP18A2FS8X9VRCCC4S7R", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"Fifteen writers respond in fiction to Italo Calvino's 1967 essay on cybernetics and myth, paired with a companion album, using the generative-AI moment as a mirror held up to older mythic and oral world-building traditions.\\""}, {"row_id": "works-dominguez-matrix-vegetal", "extraction": {"classification_basis": "decisive_move describes a video installation about plant-healing and quantum-inspired technology, with no generative-model recursive training loop described (Step 1 not cleared); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY35BP1EXJNZH7HKT9G63WXZ", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BP1MJFC774KMF7PTBDCN", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"A video installation braids Peruvian plant-healing practices together with 'quantum-inspired' technology, treating indeterminacy and non-Western epistemics of plant communication as equally valid registers of knowledge alongside computation.\\""}, {"row_id": "works-rahal-mythmachine", "extraction": {"classification_basis": "decisive_move describes a live, real-time audio-reactive feedback loop (behavior responding to ambient sound), not model-generated output recycled as training data across discrete generations — a genuinely different mechanism from recursive training (Step 1 not cleared); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY35BP1W1JMB5W77TAGX92AE", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BP22P73T7HRSR03F230X", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"An AI-driven virtual biome of post-human creatures listens to and choreographs itself from ambient audio feedback captured live in the gallery, proposing folklore-derived 'other' intelligences as an alternative to extractive machine learning.\\""}, {"row_id": "works-giraud-feral-epoch-1", "extraction": {"classification_basis": "decisive_move states successive human ARTISTS feed one continuous AI across generations of human curators, not the model's own prior-generation output fed back as training data — this is ConceptCharter Step 2's named case (trains on human-authored material across generations of human feeders, without a demonstrable model-generation-to-model-generation loop); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY35BP29XZJENYD8W032W6SM", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BP2FZ9DM3VDS2H627T1S", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"First chapter of a planned 1,000-year, 32-generation project in which successive artists 'feed' one AI so it can eventually make a film witnessing humanity's end — a deliberately glacial experiment in what a machine 'learns' across centuries rather than scraped-in-seconds data.\\""}, {"row_id": "works-cheng-thousand-lives-bob", "extraction": {"classification_basis": "decisive_move describes live, continuous belief-updating inference (a running simulation), not discrete-generation retraining on the model's own prior output (Step 1 not cleared — inference-time belief updating is a different mechanism from recursive training); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY35BP2NBKNYKDACQNBF8Q3W", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BP2WJD0XPVKV4YKVJCS4", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"Extends Cheng's neurosymbolic autonomous-agent architecture (originally built for BOB, 2018-19) into a live, indefinitely-running simulation of a pet turtle's daily belief-updating - an actually-executing inferential AI system exhibited as artwork rather than a fixed narrative or render.\\""}], "status": "draft", "revision": 1, "created_at": "2026-07-21T20:20:00.739421Z", "created_by": "urn:mrr:agent-role:01KY35BNKB3C05NTXYHEKC97SV", "api_version": "mrr/v1alpha1", "practice_id": "urn:mrr:practice:01KY35BNKB3C05NTXYHEKC97SX", "protocol_id": "urn:mrr:method-protocol:01KY35BNPEKEBN95V1MEGVWWSK", "question_id": "urn:mrr:question-model:01KY35BNMVM9WN2AKY6QBKNZJ4", "content_hash": "sha256:a0ec654f351e873dae1605d606cd41914587fe3a7227c572f92eaefe07640963", "sensitivity_analysis_results": [{"outcome": "unsupported", "variation_entry_id": "corroboration-floor-v1", "applies_to_analysis": "instantiation-vs-reference-classification", "matches_base_outcome": false, "included_source_count": 15, "verified_source_count": 14, "distinct_independent_supporting_family_count": 1, "distinct_independent_contradicting_family_count": 13}, {"outcome": "supported", "variation_entry_id": "corroboration-floor-v1", "applies_to_analysis": "model-collapse-mechanism-theory-confirmation", "matches_base_outcome": true, "included_source_count": 3, "verified_source_count": 3, "distinct_independent_supporting_family_count": 3, "distinct_independent_contradicting_family_count": 0}]}
urn:mrr:evidence-matrix:01KY35BP33JVF45T30NQW9FJX4	2	mrr/v1alpha1	EvidenceMatrix	urn:mrr:practice:01KY35BNKB3C05NTXYHEKC97SX	2026-07-21 20:20:00.752153+00	urn:mrr:agent-role:01KY35BNKB3C05NTXYHEKC97SV	sha256:7a8ec207d47ba4104587981c19824f1750831e126a49bd5739bdc4a6528d77e6	\N	null	{"id": "urn:mrr:evidence-matrix:01KY35BP33JVF45T30NQW9FJX4", "kind": "EvidenceMatrix", "rows": [{"row_id": "theory-shumailov-curse-of-recursion", "extraction": {"classification_basis": "tags: [\\"maschine/ki\\",\\"computation\\",\\"fehler\\"]; summary: \\"Shows generative models degrade when trained on their own output — model collapse\\" — a primary theoretical source directly describing the mechanism; classified supports."}, "source_record_id": "urn:mrr:source-record:01KY35BNVD4H4MRYQRJA5ZH9QN", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BNVPFM57RM9W5BZJVX4Q", "verification_status": "verified", "claim_relevant_finding": "Shows generative models degrade when trained on their own output — model collapse: the tails of the distribution vanish first. Peer-reviewed as 'AI models collapse when trained on recursively generated data', Nature 631 (2024); open access on arXiv."}, {"row_id": "theory-alemohammad-self-consuming-mad", "extraction": {"classification_basis": "tags: [\\"maschine/ki\\",\\"computation\\",\\"fehler\\"]; summary: \\"autophagous training loops across image models ... progressively decays — termed Model Autophagy Disorder (MAD)\\" — a primary theoretical source, independent author team and venue from shumailov/gerstgrasser; classified supports."}, "source_record_id": "urn:mrr:source-record:01KY35BNVYMFN1ZTAEE9D192DJ", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BNW6DDEJDPW63VS7XTKR", "verification_status": "verified", "claim_relevant_finding": "Analyzes autophagous training loops across image models: without enough fresh real data in each generation, quality or diversity progressively decays — termed Model Autophagy Disorder (MAD). Open access on arXiv; no further formal venue recorded in the atlas."}, {"row_id": "theory-gerstgrasser-model-collapse-inevitable", "extraction": {"classification_basis": "tags: [\\"maschine/ki\\",\\"computation\\"]; summary: \\"accumulating synthetic data alongside real data ... bounds the error across LLMs, diffusion models and VAEs\\" — a primary theoretical source corroborating the same mechanism from a third, independent author team and venue; classified supports."}, "source_record_id": "urn:mrr:source-record:01KY35BNWDGA9YK34T1M1W4MYV", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BNWMBJDXBTKXQBKWZ95H", "verification_status": "verified", "claim_relevant_finding": "Shows collapse is not fate: accumulating synthetic data alongside real data — instead of replacing it — bounds the error across LLMs, diffusion models and VAEs. Also published at COLM 2024; open access on arXiv."}, {"row_id": "works-heaney-ent-non-earthly-delights", "extraction": {"classification_basis": "decisive_move describes a physical sculpture about quantum computing and surveillance capitalism, with no documented model-generation-to-model-generation training loop at all (ConceptCharter instantiate-vs-reference-v1 Step 2: thematizes AI surveillance rather than instantiating the mechanism); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY35BNWYVBGMAHR6BVTM7HGM", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BNX5TJDWDTXA2WRZTTS3", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"A physical 'quantum cyborg' sculpture (mild steel, fibreglass, acrylic, plus AR layers) staging Bosch's Garden of Earthly Delights as a warning about quantum computing's coming acceleration of AI-driven surveillance capitalism; Heaney explicitly frames dissolving/'sliming' as a strategy of resistance against detection systems.\\""}, {"row_id": "works-wilding-ai-lab", "extraction": {"classification_basis": "decisive_move describes examining the training/generation process as artistic material, but discloses no demonstrable model-output-fed-back-as-training-input loop across >=2 generations (Step 1 not cleared); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY35BNXBX6JWW8HSCV7BN0AZ", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BNXJMP2QQXCBWCZ88EBW", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"An open, participatory lab inside a spatial-audio dome where invited artists collectively 'reopen the black box' of generative AI models in public, treating the training/generation process itself — not just its output — as the artistic material.\\""}, {"row_id": "works-chronus-ai-delivered-abject", "extraction": {"classification_basis": "decisive_move describes GAN-trained works probing epistemological breakdown, but discloses no recursive model-generation-to-model-generation training loop (Step 1 not cleared); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY35BNXT9YWHA6VGD72HF3JB", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BNY24V3FCKR31JVEH672", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"Group exhibition of GAN-trained films, a real-time AI dialogue-generating website, and an 'artificial counter-intelligence machine,' collectively probing where AI's competence gives way to abjection and epistemological breakdown.\\""}, {"row_id": "works-baudelaire-en-attendant-le-recit", "extraction": {"classification_basis": "decisive_move describes live inference-time conversation between already-trained models, not model-generated output fed back as training data for a subsequent generation (Step 1 not cleared — a looping CONVERSATION, not a looping TRAINING process); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY35BNY91H52992031D9R6MZ", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BNYG4N72M78Z0JTTW20W", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"Three chatbot models (ChatGPT, Claude, Mistral) are each given a character and voice through a speaker on one of three benches arranged in a triangle, and left to converse live about AI anxiety and 'the end of grand narratives' — an unscripted, looping machine dialogue restaged as improvised theatre, restarting every seven minutes.\\""}, {"row_id": "works-kurant-errorism", "extraction": {"classification_basis": "decisive_move states the model is trained on \\"her own writings\\" (the artist's own prior, human-authored text), not a PRIOR GENERATION OF THE MODEL'S OWN output — this is exactly ConceptCharter instantiate-vs-reference-v1 Step 2's named case (\\"trains on human-authored material (even the artist's own prior writing) without a demonstrable model-generation-to-model-generation loop\\"); a genuinely ambiguous, flagged case (task-packets/K1-T04.yaml derived_decisions (e)), resolved here per the charter's own Step 2 text; classified references-only/contradicts, not qualifies, because the atlas's own decisive_move discloses the input as the artist's own writing, not the model's own prior-generation output."}, "source_record_id": "urn:mrr:source-record:01KY35BNYQAAM6WDC1AEBF45BR", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BNYYP1DWG6HDV9MVFWV1", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"Kurant feeds her own writings into GPT-2 and GPT-3 and renders the output as a holographic animation, literally closing the loop of a model trained on and regurgitating one author's own words — a small, self-contained demonstration of the recursive self-consumption/collapse dynamic at stake in cluster 7.\\""}, {"row_id": "works-raikhy-hallucinations-of-an-artifact", "extraction": {"classification_basis": "decisive_move describes live performance collaboration with a generative-AI avatar, with no documented recursive training loop across generations (Step 1 not cleared); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY35BNZ4C9VJZ4J4GJ6E4909", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BNZAMXYD9GC65G7K4MVC", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"Dancers improvise alongside a generative-AI avatar to invent speculative alternate lives for a prehistoric Indus Valley bronze statue, using an AI model as collaborator in reanimating an artifact whose original meaning is otherwise irrecoverable.\\""}, {"row_id": "works-ubermorgen-next-biennial-machine", "extraction": {"classification_basis": "decisive_move states the model is trained once on real Biennial/Whitney archives and then generates continuously, with no described retraining on its own prior-generation output (Step 1 not cleared); classified references-only/contradicts. Atlas verify_status is 'toVerify', not 'verified' — mapped to CorpusEntry verification_status 'pending' (task-packets/K1-T04.yaml derived_decisions (c)). The row is never dropped from the frozen matrix (MRR-MTH-015). Its own 'contradicts' evidence_relation still groups it into the contradicting-entry set the claim's own assertion text is built from (mrr.services.node_runtime.synthesis_executor._build_assertion has no verification-status filter), but mrr.domain.source_independence.distinct_independent_source_family_count only counts 'verified' rows, so this row contributes zero to the numeric contradicting-family tally that actually determines eligibility (13, not 14, distinct families) — the same 'verified'-only rule also excludes it from the separate min_included_sources kill-condition count. The eligibility outcome is unaffected either way."}, "source_record_id": "urn:mrr:source-record:01KY35BNZH98AF2VN023JZDB4W", "verification_status": "pending", "claim_relevant_finding": "decisive_move: \\"An AI trained on real Biennial and Whitney archives endlessly hallucinates fake artist biographies and press releases, exposing algorithmic curation's absurdity by actually letting a machine attempt it, live, forever.\\""}, {"row_id": "works-mavropoulou-sleight-of-the-machine", "extraction": {"classification_basis": "decisive_move describes a single AI video model's inference-time failures kept on screen, with no documented recursive retraining loop across generations (Step 1 not cleared); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY35BNZRE5MFFTKPPM0JWTW1", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BNZYJG0Q9K8F473T30DB", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"An AI video model is cast as a stage magician performing sleight-of-hand; rather than concealing the model's characteristic failures (hands multiplying, morphing, defying physics), the film keeps every glitch on screen as the actual 'trick' — generative failure turned into the evidentiary content.\\""}, {"row_id": "works-hammond-v3-model-collapse", "extraction": {"classification_basis": "decisive_move states plainly: \\"each exhibition's own photographs and collages are fed back as training data for the next\\" — model-GENERATED output (the prior exhibition's own photographs/collages) fed back as training input for a SUBSEQUENT generation of a continuous pipeline, across at least three named generations (V1-V4) — clears ConceptCharter instantiate-vs-reference-v1 Step 1 cleanly, and the atlas's own text names the result \\"literalizes AI model collapse\\"; classified instantiates/supports."}, "source_record_id": "urn:mrr:source-record:01KY35BP05ZVMXH38B68J4RKHQ", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BP0BS2YDKEPRPG0N0VST", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"Third chapter of a four-part project in which each exhibition's own photographs and collages are fed back as training data for the next - literalizes AI model collapse as a visible, physically-installed material process, and draws an explicit parallel between data mining and geological mining extraction.\\""}, {"row_id": "works-hailesilassie-6500-alphabets", "extraction": {"classification_basis": "decisive_move describes a physical installation of digitized pictographs proposing an alternative epistemics, with no generative-model recursive training loop described at all (Step 1 not cleared, not even a generative-AI production pipeline); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY35BP0JYJ39T8YWS521NHYR", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BP0S7PBYYK130S9CXKX8", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"Large-scale dome installation built from 6,500 digitized African pictographs, syllabaries and ideographs (extending the artist's 2019–2023 'Ancestral Algorithm' project) that reframes 'algorithm' as 'algo + rhythm', proposing indigenous knowledge systems as an alternative computational epistemics rather than an ornament to it.\\""}, {"row_id": "works-salu-ginzburg-cybernetics-or-ghosts", "extraction": {"classification_basis": "decisive_move describes human-authored fiction responding to a 1967 essay, with no generative-model training loop of any kind described (Step 1 not cleared, not even a generative-AI production pipeline); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY35BP10KEQADBQXGZD6B7MH", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BP18A2FS8X9VRCCC4S7R", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"Fifteen writers respond in fiction to Italo Calvino's 1967 essay on cybernetics and myth, paired with a companion album, using the generative-AI moment as a mirror held up to older mythic and oral world-building traditions.\\""}, {"row_id": "works-dominguez-matrix-vegetal", "extraction": {"classification_basis": "decisive_move describes a video installation about plant-healing and quantum-inspired technology, with no generative-model recursive training loop described (Step 1 not cleared); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY35BP1EXJNZH7HKT9G63WXZ", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BP1MJFC774KMF7PTBDCN", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"A video installation braids Peruvian plant-healing practices together with 'quantum-inspired' technology, treating indeterminacy and non-Western epistemics of plant communication as equally valid registers of knowledge alongside computation.\\""}, {"row_id": "works-rahal-mythmachine", "extraction": {"classification_basis": "decisive_move describes a live, real-time audio-reactive feedback loop (behavior responding to ambient sound), not model-generated output recycled as training data across discrete generations — a genuinely different mechanism from recursive training (Step 1 not cleared); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY35BP1W1JMB5W77TAGX92AE", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BP22P73T7HRSR03F230X", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"An AI-driven virtual biome of post-human creatures listens to and choreographs itself from ambient audio feedback captured live in the gallery, proposing folklore-derived 'other' intelligences as an alternative to extractive machine learning.\\""}, {"row_id": "works-giraud-feral-epoch-1", "extraction": {"classification_basis": "decisive_move states successive human ARTISTS feed one continuous AI across generations of human curators, not the model's own prior-generation output fed back as training data — this is ConceptCharter Step 2's named case (trains on human-authored material across generations of human feeders, without a demonstrable model-generation-to-model-generation loop); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY35BP29XZJENYD8W032W6SM", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BP2FZ9DM3VDS2H627T1S", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"First chapter of a planned 1,000-year, 32-generation project in which successive artists 'feed' one AI so it can eventually make a film witnessing humanity's end — a deliberately glacial experiment in what a machine 'learns' across centuries rather than scraped-in-seconds data.\\""}, {"row_id": "works-cheng-thousand-lives-bob", "extraction": {"classification_basis": "decisive_move describes live, continuous belief-updating inference (a running simulation), not discrete-generation retraining on the model's own prior output (Step 1 not cleared — inference-time belief updating is a different mechanism from recursive training); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY35BP2NBKNYKDACQNBF8Q3W", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY35BP2WJD0XPVKV4YKVJCS4", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"Extends Cheng's neurosymbolic autonomous-agent architecture (originally built for BOB, 2018-19) into a live, indefinitely-running simulation of a pet turtle's daily belief-updating - an actually-executing inferential AI system exhibited as artwork rather than a fixed narrative or render.\\""}], "status": "active", "revision": 2, "created_at": "2026-07-21T20:20:00.752153+00:00", "created_by": "urn:mrr:agent-role:01KY35BNKB3C05NTXYHEKC97SV", "api_version": "mrr/v1alpha1", "practice_id": "urn:mrr:practice:01KY35BNKB3C05NTXYHEKC97SX", "protocol_id": "urn:mrr:method-protocol:01KY35BNPEKEBN95V1MEGVWWSK", "question_id": "urn:mrr:question-model:01KY35BNMVM9WN2AKY6QBKNZJ4", "content_hash": "sha256:7a8ec207d47ba4104587981c19824f1750831e126a49bd5739bdc4a6528d77e6", "sensitivity_analysis_results": [{"outcome": "unsupported", "variation_entry_id": "corroboration-floor-v1", "applies_to_analysis": "instantiation-vs-reference-classification", "matches_base_outcome": false, "included_source_count": 15, "verified_source_count": 14, "distinct_independent_supporting_family_count": 1, "distinct_independent_contradicting_family_count": 13}, {"outcome": "supported", "variation_entry_id": "corroboration-floor-v1", "applies_to_analysis": "model-collapse-mechanism-theory-confirmation", "matches_base_outcome": true, "included_source_count": 3, "verified_source_count": 3, "distinct_independent_supporting_family_count": 3, "distinct_independent_contradicting_family_count": 0}]}
urn:mrr:claim:01KY35BP43WR5J45ZNFFP09Q0K	1	mrr/v1alpha1	Claim	urn:mrr:practice:01KY35BNKB3C05NTXYHEKC97SX	2026-07-21 20:20:00.771399+00	urn:mrr:agent-role:01KY35BNKB3C05NTXYHEKC97SV	sha256:e39d2ebb0e9cea1e7691960bc6325d4dc9a06e52bf2ef0b3aa7753800ed46c2e	\N	null	{"id": "urn:mrr:claim:01KY35BP43WR5J45ZNFFP09Q0K", "kind": "Claim", "scope": {"time": "atlas snapshots pinned 2026-07-21 at the recorded content hashes", "conditions": ["work must be catalogued in the pinned works-atlas snapshot, not merely mentioned in secondary commentary", "theory-side corroboration is drawn only from the pinned theory-atlas snapshot's own model-collapse keyword match over tags/summary/work"], "population": "works in the pinned works-atlas snapshot (corpora/model-collapse/works-atlas.snapshot.json, sha256:9d14e877efb245cc04b8451734b26285a274dda0418f5131db257d2e4312d373, 214 verified data/AI artworks) whose own `clusters` array contains 7 (\\"AI self-consumption\\" per src/data/field/clusters.json) — corroborated against the pinned theory-atlas snapshot (corpora/model-collapse/theory-atlas.snapshot.json, sha256:f712ea4e9c6b9137fa180ad91e73a86d8d09862792f33174c77acd76a891e610, 87 provenance-verified sources) for the model-collapse mechanism's own existence"}, "status": "draft", "revision": 1, "assertion": "Analysis 'instantiation-vs-reference-classification'. Supporting: decisive_move: \\"Third chapter of a four-part project in which each exhibition's own photographs and collages are fed back as training data for the next - literalizes AI model collapse as a visible, physically-installed material process, and draws an explicit parallel between data mining and geological mining extraction.\\" Contradicting: decisive_move: \\"A physical 'quantum cyborg' sculpture (mild steel, fibreglass, acrylic, plus AR layers) staging Bosch's Garden of Earthly Delights as a warning about quantum computing's coming acceleration of AI-driven surveillance capitalism; Heaney explicitly frames dissolving/'sliming' as a strategy of resistance against detection systems.\\" decisive_move: \\"An open, participatory lab inside a spatial-audio dome where invited artists collectively 'reopen the black box' of generative AI models in public, treating the training/generation process itself — not just its output — as the artistic material.\\" decisive_move: \\"Group exhibition of GAN-trained films, a real-time AI dialogue-generating website, and an 'artificial counter-intelligence machine,' collectively probing where AI's competence gives way to abjection and epistemological breakdown.\\" decisive_move: \\"Three chatbot models (ChatGPT, Claude, Mistral) are each given a character and voice through a speaker on one of three benches arranged in a triangle, and left to converse live about AI anxiety and 'the end of grand narratives' — an unscripted, looping machine dialogue restaged as improvised theatre, restarting every seven minutes.\\" decisive_move: \\"Kurant feeds her own writings into GPT-2 and GPT-3 and renders the output as a holographic animation, literally closing the loop of a model trained on and regurgitating one author's own words — a small, self-contained demonstration of the recursive self-consumption/collapse dynamic at stake in cluster 7.\\" decisive_move: \\"Dancers improvise alongside a generative-AI avatar to invent speculative alternate lives for a prehistoric Indus Valley bronze statue, using an AI model as collaborator in reanimating an artifact whose original meaning is otherwise irrecoverable.\\" decisive_move: \\"An AI trained on real Biennial and Whitney archives endlessly hallucinates fake artist biographies and press releases, exposing algorithmic curation's absurdity by actually letting a machine attempt it, live, forever.\\" decisive_move: \\"An AI video model is cast as a stage magician performing sleight-of-hand; rather than concealing the model's characteristic failures (hands multiplying, morphing, defying physics), the film keeps every glitch on screen as the actual 'trick' — generative failure turned into the evidentiary content.\\" decisive_move: \\"Large-scale dome installation built from 6,500 digitized African pictographs, syllabaries and ideographs (extending the artist's 2019–2023 'Ancestral Algorithm' project) that reframes 'algorithm' as 'algo + rhythm', proposing indigenous knowledge systems as an alternative computational epistemics rather than an ornament to it.\\" decisive_move: \\"Fifteen writers respond in fiction to Italo Calvino's 1967 essay on cybernetics and myth, paired with a companion album, using the generative-AI moment as a mirror held up to older mythic and oral world-building traditions.\\" decisive_move: \\"A video installation braids Peruvian plant-healing practices together with 'quantum-inspired' technology, treating indeterminacy and non-Western epistemics of plant communication as equally valid registers of knowledge alongside computation.\\" decisive_move: \\"An AI-driven virtual biome of post-human creatures listens to and choreographs itself from ambient audio feedback captured live in the gallery, proposing folklore-derived 'other' intelligences as an alternative to extractive machine learning.\\" decisive_move: \\"First chapter of a planned 1,000-year, 32-generation project in which successive artists 'feed' one AI so it can eventually make a film witnessing humanity's end — a deliberately glacial experiment in what a machine 'learns' across centuries rather than scraped-in-seconds data.\\" decisive_move: \\"Extends Cheng's neurosymbolic autonomous-agent architecture (originally built for BOB, 2018-19) into a live, indefinitely-running simulation of a pet turtle's daily belief-updating - an actually-executing inferential AI system exhibited as artwork rather than a fixed narrative or render.\\"", "claim_type": "interpretive", "created_at": "2026-07-21T20:20:00.771399Z", "created_by": "urn:mrr:agent-role:01KY35BNKB3C05NTXYHEKC97SV", "api_version": "mrr/v1alpha1", "practice_id": "urn:mrr:practice:01KY35BNKB3C05NTXYHEKC97SX", "proposer_id": "urn:mrr:agent-role:01KY35BNKB3C05NTXYHEKC97SV", "uncertainty": [], "content_hash": "sha256:e39d2ebb0e9cea1e7691960bc6325d4dc9a06e52bf2ef0b3aa7753800ed46c2e", "dependencies": [], "correction_ids": [], "known_unknowns": [], "verification_ids": [], "source_family_ids": [], "evidence_relations": ["urn:mrr:evidence-anchor:01KY35BP0BS2YDKEPRPG0N0VST"], "counterevidence_relations": ["urn:mrr:evidence-anchor:01KY35BNX5TJDWDTXA2WRZTTS3", "urn:mrr:evidence-anchor:01KY35BNXJMP2QQXCBWCZ88EBW", "urn:mrr:evidence-anchor:01KY35BNY24V3FCKR31JVEH672", "urn:mrr:evidence-anchor:01KY35BNYG4N72M78Z0JTTW20W", "urn:mrr:evidence-anchor:01KY35BNYYP1DWG6HDV9MVFWV1", "urn:mrr:evidence-anchor:01KY35BNZAMXYD9GC65G7K4MVC", "urn:mrr:evidence-anchor:01KY35BNZYJG0Q9K8F473T30DB", "urn:mrr:evidence-anchor:01KY35BP0S7PBYYK130S9CXKX8", "urn:mrr:evidence-anchor:01KY35BP18A2FS8X9VRCCC4S7R", "urn:mrr:evidence-anchor:01KY35BP1MJFC774KMF7PTBDCN", "urn:mrr:evidence-anchor:01KY35BP22P73T7HRSR03F230X", "urn:mrr:evidence-anchor:01KY35BP2FZ9DM3VDS2H627T1S", "urn:mrr:evidence-anchor:01KY35BP2WJD0XPVKV4YKVJCS4"]}
urn:mrr:claim:01KY35BP43WR5J45ZNFFP09Q0K	2	mrr/v1alpha1	Claim	urn:mrr:practice:01KY35BNKB3C05NTXYHEKC97SX	2026-07-21 20:20:00.781955+00	urn:mrr:agent-role:01KY35BNKB3C05NTXYHEKC97SV	sha256:a512ad6fb26910059e90b932af4ae5342ca561e450c933abb3bda27b37f568af	\N	null	{"id": "urn:mrr:claim:01KY35BP43WR5J45ZNFFP09Q0K", "kind": "Claim", "scope": {"time": "atlas snapshots pinned 2026-07-21 at the recorded content hashes", "conditions": ["work must be catalogued in the pinned works-atlas snapshot, not merely mentioned in secondary commentary", "theory-side corroboration is drawn only from the pinned theory-atlas snapshot's own model-collapse keyword match over tags/summary/work"], "population": "works in the pinned works-atlas snapshot (corpora/model-collapse/works-atlas.snapshot.json, sha256:9d14e877efb245cc04b8451734b26285a274dda0418f5131db257d2e4312d373, 214 verified data/AI artworks) whose own `clusters` array contains 7 (\\"AI self-consumption\\" per src/data/field/clusters.json) — corroborated against the pinned theory-atlas snapshot (corpora/model-collapse/theory-atlas.snapshot.json, sha256:f712ea4e9c6b9137fa180ad91e73a86d8d09862792f33174c77acd76a891e610, 87 provenance-verified sources) for the model-collapse mechanism's own existence"}, "status": "under_review", "revision": 2, "assertion": "Analysis 'instantiation-vs-reference-classification'. Supporting: decisive_move: \\"Third chapter of a four-part project in which each exhibition's own photographs and collages are fed back as training data for the next - literalizes AI model collapse as a visible, physically-installed material process, and draws an explicit parallel between data mining and geological mining extraction.\\" Contradicting: decisive_move: \\"A physical 'quantum cyborg' sculpture (mild steel, fibreglass, acrylic, plus AR layers) staging Bosch's Garden of Earthly Delights as a warning about quantum computing's coming acceleration of AI-driven surveillance capitalism; Heaney explicitly frames dissolving/'sliming' as a strategy of resistance against detection systems.\\" decisive_move: \\"An open, participatory lab inside a spatial-audio dome where invited artists collectively 'reopen the black box' of generative AI models in public, treating the training/generation process itself — not just its output — as the artistic material.\\" decisive_move: \\"Group exhibition of GAN-trained films, a real-time AI dialogue-generating website, and an 'artificial counter-intelligence machine,' collectively probing where AI's competence gives way to abjection and epistemological breakdown.\\" decisive_move: \\"Three chatbot models (ChatGPT, Claude, Mistral) are each given a character and voice through a speaker on one of three benches arranged in a triangle, and left to converse live about AI anxiety and 'the end of grand narratives' — an unscripted, looping machine dialogue restaged as improvised theatre, restarting every seven minutes.\\" decisive_move: \\"Kurant feeds her own writings into GPT-2 and GPT-3 and renders the output as a holographic animation, literally closing the loop of a model trained on and regurgitating one author's own words — a small, self-contained demonstration of the recursive self-consumption/collapse dynamic at stake in cluster 7.\\" decisive_move: \\"Dancers improvise alongside a generative-AI avatar to invent speculative alternate lives for a prehistoric Indus Valley bronze statue, using an AI model as collaborator in reanimating an artifact whose original meaning is otherwise irrecoverable.\\" decisive_move: \\"An AI trained on real Biennial and Whitney archives endlessly hallucinates fake artist biographies and press releases, exposing algorithmic curation's absurdity by actually letting a machine attempt it, live, forever.\\" decisive_move: \\"An AI video model is cast as a stage magician performing sleight-of-hand; rather than concealing the model's characteristic failures (hands multiplying, morphing, defying physics), the film keeps every glitch on screen as the actual 'trick' — generative failure turned into the evidentiary content.\\" decisive_move: \\"Large-scale dome installation built from 6,500 digitized African pictographs, syllabaries and ideographs (extending the artist's 2019–2023 'Ancestral Algorithm' project) that reframes 'algorithm' as 'algo + rhythm', proposing indigenous knowledge systems as an alternative computational epistemics rather than an ornament to it.\\" decisive_move: \\"Fifteen writers respond in fiction to Italo Calvino's 1967 essay on cybernetics and myth, paired with a companion album, using the generative-AI moment as a mirror held up to older mythic and oral world-building traditions.\\" decisive_move: \\"A video installation braids Peruvian plant-healing practices together with 'quantum-inspired' technology, treating indeterminacy and non-Western epistemics of plant communication as equally valid registers of knowledge alongside computation.\\" decisive_move: \\"An AI-driven virtual biome of post-human creatures listens to and choreographs itself from ambient audio feedback captured live in the gallery, proposing folklore-derived 'other' intelligences as an alternative to extractive machine learning.\\" decisive_move: \\"First chapter of a planned 1,000-year, 32-generation project in which successive artists 'feed' one AI so it can eventually make a film witnessing humanity's end — a deliberately glacial experiment in what a machine 'learns' across centuries rather than scraped-in-seconds data.\\" decisive_move: \\"Extends Cheng's neurosymbolic autonomous-agent architecture (originally built for BOB, 2018-19) into a live, indefinitely-running simulation of a pet turtle's daily belief-updating - an actually-executing inferential AI system exhibited as artwork rather than a fixed narrative or render.\\"", "claim_type": "interpretive", "created_at": "2026-07-21T20:20:00.781955+00:00", "created_by": "urn:mrr:agent-role:01KY35BNKB3C05NTXYHEKC97SV", "api_version": "mrr/v1alpha1"