urn:mrr:claim:01KY35CSBGPJ7Z02N6NDY25TBH	1	mrr/v1alpha1	Claim	urn:mrr:practice:01KY35CRPPECQGP0G6K5T7PDYE	2026-07-21 20:20:36.848662+00	urn:mrr:agent-role:01KY35CRPPECQGP0G6K5T7PDYC	sha256:18159f2733e9f6d74dcbcaae74a42f06b5e7f9de533f31cf30660e107ad10a53	\N	null	{"id": "urn:mrr:claim:01KY35CSBGPJ7Z02N6NDY25TBH", "kind": "Claim", "scope": {"time": "atlas snapshots pinned 2026-07-21 at the recorded content hashes", "conditions": ["work must be catalogued in the pinned works-atlas snapshot, not merely mentioned in secondary commentary", "theory-side corroboration is drawn only from the pinned theory-atlas snapshot's own model-collapse keyword match over tags/summary/work"], "population": "works in the pinned works-atlas snapshot (corpora/model-collapse/works-atlas.snapshot.json, sha256:9d14e877efb245cc04b8451734b26285a274dda0418f5131db257d2e4312d373, 214 verified data/AI artworks) whose own `clusters` array contains 7 (\\"AI self-consumption\\" per src/data/field/clusters.json) — corroborated against the pinned theory-atlas snapshot (corpora/model-collapse/theory-atlas.snapshot.json, sha256:f712ea4e9c6b9137fa180ad91e73a86d8d09862792f33174c77acd76a891e610, 87 provenance-verified sources) for the model-collapse mechanism's own existence"}, "status": "draft", "revision": 1, "assertion": "Analysis 'model-collapse-mechanism-theory-confirmation'. Supporting: Shows generative models degrade when trained on their own output — model collapse: the tails of the distribution vanish first. Peer-reviewed as 'AI models collapse when trained on recursively generated data', Nature 631 (2024); open access on arXiv. Analyzes autophagous training loops across image models: without enough fresh real data in each generation, quality or diversity progressively decays — termed Model Autophagy Disorder (MAD). Open access on arXiv; no further formal venue recorded in the atlas. Shows collapse is not fate: accumulating synthetic data alongside real data — instead of replacing it — bounds the error across LLMs, diffusion models and VAEs. Also published at COLM 2024; open access on arXiv.", "claim_type": "observational", "created_at": "2026-07-21T20:20:36.848662Z", "created_by": "urn:mrr:agent-role:01KY35CRPPECQGP0G6K5T7PDYC", "api_version": "mrr/v1alpha1", "practice_id": "urn:mrr:practice:01KY35CRPPECQGP0G6K5T7PDYE", "proposer_id": "urn:mrr:agent-role:01KY35CRPPECQGP0G6K5T7PDYC", "uncertainty": [], "content_hash": "sha256:18159f2733e9f6d74dcbcaae74a42f06b5e7f9de533f31cf30660e107ad10a53", "dependencies": [], "correction_ids": [], "known_unknowns": [], "verification_ids": [], "source_family_ids": [], "evidence_relations": ["urn:mrr:evidence-anchor:01KY35CRY4Y8G2ZAN7TTY6VKSG", "urn:mrr:evidence-anchor:01KY35CRYVQ4YQBC5RBG8GD3QB", "urn:mrr:evidence-anchor:01KY35CRZEKXBRMTKSFRZGWCK2"], "counterevidence_relations": []}
